/* 학습 해설
 * RCU-sync destructor·REPLAY 정리와 callback barrier
 * RCU기반reader경로전환의상태머신과updater공유를실제원문으로읽어graceperiod기술의원리를배웁니다.
 * dtor는PASSED와활성gp_count를잘못된수명 조건으로warning합니다. 잠금아래REPLAY를EXIT로바꾸어불필요한재예약을막고현재 state를저장합니다. IDLE이아니면rcu_barrier로진행중 callback 완료를기다린뒤IDLE을확인합니다. rcu_barrier는queuedcallback 완료규약이며언제나새RCUgraceperiod하나를기다리는synchronize_rcu와같은약속은아닙니다.
 * 모든 updater의 enter/exit 사용이끝난뒤객체 free전에dtor를수행합니다. warning을활성 updater 강제취소API로사용하지않습니다. callback 수명과객체 수명을정리하는목적을 barrier의정확한계약과연결합니다.
 */
void rcu_sync_dtor(struct rcu_sync *rsp)
{
	int gp_state;

	WARN_ON_ONCE(READ_ONCE(rsp->gp_state) == GP_PASSED);

	spin_lock_irq(&rsp->rss_lock);
	WARN_ON_ONCE(rsp->gp_count);
	if (rsp->gp_state == GP_REPLAY)
		WRITE_ONCE(rsp->gp_state, GP_EXIT);
	gp_state = rsp->gp_state;
	spin_unlock_irq(&rsp->rss_lock);

	if (gp_state != GP_IDLE) {
		rcu_barrier();
		WARN_ON_ONCE(rsp->gp_state != GP_IDLE);
	}
}

/* 학습 해설
 * Rcuwait 표현·하나의 RCU task 포인터와 active 조회
 * 단일 task가 RCU로 안전하게 기다리는 방식과 조건·signal·timeout의 판정 순서를 실제 소스에서 배웁니다.
 * rcuwait 구조체에는 RCU로 보호하는 task 포인터가 하나 있습니다. 초기값은 NULL입니다. 기다리는 task는 조건을 검사하거나 잠들어 있는 동안 이 포인터에 자신을 등록하고, 대기가 끝나면 NULL로 되돌립니다. active 조회는 그 순간 포인터가 NULL인지 확인할 뿐입니다. 잠금 소유권이나 task가 실제로 잠들었는지는 보장하지 않습니다. 여러 task를 리스트에 등록하는 일반 waitqueue와 구별하세요.
 * 하나의 조건을 기다리는 단일 waiter에 사용합니다. 같은 구조체의 task 포인터 쓰기는 호출자 규약으로 직렬화하세요. active 값만으로 task 수명이나 잠금 소유권을 판단하지 말고, 여러 task를 동시에 같은 포인터에 등록하지 마세요.
 */
struct rcuwait {
	struct task_struct __rcu *task;
};

#define __RCUWAIT_INITIALIZER(name)		\
	{ .task = NULL, }

static inline void rcuwait_init(struct rcuwait *w)
{
	w->task = NULL;
}

/*
 * Note: this provides no serialization and, just as with waitqueues,
 * requires care to estimate as to whether or not the wait is active.
 */
static inline int rcuwait_active(struct rcuwait *w)
{
	return !!rcu_access_pointer(w->task);
}

extern int rcuwait_wake_up(struct rcuwait *w);

/*
 * The caller is responsible for locking around rcuwait_wait_event(),
 * and [prepare_to/finish]_rcuwait() such that writes to @task are
 * properly serialized.
 */

/* 학습 해설
 * Rcuwait finish·포인터 NULL과 TASK_RUNNING 복구
 * 단일 task가 RCU로 안전하게 기다리는 방식과 조건·signal·timeout의 판정 순서를 실제 소스에서 배웁니다.
 * finish_rcuwait는 RCU 포인터 대입으로 w->task를 NULL로 만들고, __set_current_state(TASK_RUNNING)으로 현재 task의 대기 상태를 정리합니다. 등록을 해제하는 것이므로 task나 rcuwait 객체를 메모리에서 해제하는 함수는 아닙니다. prepare와 finish 양쪽의 포인터 쓰기에 호출자의 직렬화 규칙이 적용됩니다. 등록 해제와 객체 해제를 구별해야 수명 문제를 피할 수 있습니다.
 * prepare와 finish를 직접 사용하는 코드는 등록과 정리를 짝으로 수행하세요. 객체 해제와 포인터 등록 해제를 구별합니다. 완료 뒤 active가 false라는 사실만으로 과거 참조까지 안전하게 해제할 수 있다고 판단하지 마세요.
 */
void finish_rcuwait(struct rcuwait *w)
{
	rcu_assign_pointer(w->task, NULL);
	__set_current_state(TASK_RUNNING);
}
EXPORT_SYMBOL_GPL(finish_rcuwait);

