/**
 * init_rcu_head_on_stack() - initialize on-stack rcu_head for debugobjects
 * @head: pointer to rcu_head structure to be initialized
 *
 * This function informs debugobjects of a new rcu_head structure that
 * has been allocated as an auto variable on the stack.  This function
 * is not required for rcu_head structures that are statically defined or
 * that are dynamically allocated on the heap.  This function has no
 * effect for !CONFIG_DEBUG_OBJECTS_RCU_HEAD kernel builds.
 */

/* 학습 해설
 * Rcuwait wake·RCU 보호와 반환 0의 두 원인
 * 단일 task가 RCU로 안전하게 기다리는 방식과 조건·signal·timeout의 판정 순서를 실제 소스에서 배웁니다.
 * rcuwait_wake_up은 반환값 0으로 시작하고 RCU 읽기 보호 구간에 들어갑니다. 메모리 배리어 B 뒤에 task 포인터를 읽고, 포인터가 있으면 wake_up_process의 결과를 전달합니다. task가 NULL이면 0이며, 등록된 task가 이미 실행 가능한 상태여서 깨우지 않았어도 0일 수 있습니다. 1은 task를 깨웠다는 뜻입니다. 이 함수는 대기 조건을 직접 true로 바꾸지 않습니다.
 * 조건 변경을 원문의 메모리 순서 규약에 맞춰 공개한 뒤 wake를 호출하세요. 반환값 0만으로 waiter 포인터가 없다고 단정하지 마세요. RCU의 수명 보호와 waiter 등록 쓰기의 직렬화는 별도로 지켜야 합니다.
 */
int rcuwait_wake_up(struct rcuwait *w)
{
	int ret = 0;
	struct task_struct *task;

	rcu_read_lock();

	/*
	 * Order condition vs @task, such that everything prior to the load
	 * of @task is visible. This is the condition as to why the user called
	 * rcuwait_wake() in the first place. Pairs with set_current_state()
	 * barrier (A) in rcuwait_wait_event().
	 *
	 *    WAIT                WAKE
	 *    [S] tsk = current	  [S] cond = true
	 *        MB (A)	      MB (B)
	 *    [L] cond		  [L] tsk
	 */
	smp_mb(); /* (B) */

	task = rcu_dereference(w->task);
	if (task)
		ret = wake_up_process(task);
	rcu_read_unlock();

	return ret;

/* 학습 해설
 * Waitqueue 구조·대기자와 대기열의 역할
 * 실제 Linux 대기열의 구조와 등록·조건 검사·깨움·정리 순서를 읽어 잠드는 기술의 사용 조건을 배웁니다.
 * 대기자 한 명을 표현하는 wait_queue_entry에는 flags, private, func, 이중 연결 리스트의 entry가 있습니다. private는 기본 사용에서 task를 가리키지만 사용자 콜백은 다른 문맥을 사용할 수도 있습니다. func는 깨움 요청을 처리하는 함수 포인터입니다. wait_queue_head는 리스트 head와 이를 보호하는 spinlock을 가집니다. 객체의 자료구조와 실제 task의 실행 상태를 구분하세요.
 * 여러 task가 같은 조건을 기다릴 때 대기열을 사용합니다. 기본 콜백이 private를 task로 해석하는 규약을 지키세요. 사용자 콜백으로 교체할 때는 private의 해석, 반환값, 리스트 등록과 해제 책임을 함께 정합니다.
 */
struct wait_queue_entry {
	unsigned int		flags;
	void			*private;
	wait_queue_func_t	func;
	struct list_head	entry;
};

struct wait_queue_head {
	spinlock_t		lock;
	struct list_head	head;
};
typedef struct wait_queue_head wait_queue_head_t;

struct task_struct;

/*
 * Macros for declaration and initialisaton of the datatypes
 */

#define __WAITQUEUE_INITIALIZER(name, tsk) {					\
	.private	= tsk,							\
	.func		= default_wake_function,				\
	.entry		= { NULL, NULL } }

#define DECLARE_WAITQUEUE(name, tsk)						\
	struct wait_queue_entry name = __WAITQUEUE_INITIALIZER(name, tsk)

/* 학습 해설
 * Waitqueue head 초기화·잠금과 lockdep 클래스
 * 실제 Linux 대기열의 구조와 등록·조건 검사·깨움·정리 순서를 읽어 잠드는 기술의 사용 조건을 배웁니다.
 * __init_waitqueue_head는 spinlock을 초기화하고 lockdep의 클래스와 이름을 연결한 뒤 리스트 head를 자기 참조로 만듭니다. 헤더의 init_waitqueue_head 매크로는 호출 지점의 정적 lock_class_key를 전달합니다. 정적 DECLARE_WAIT_QUEUE_HEAD는 잠금과 리스트의 정적 초기화를 제공합니다. CONFIG_LOCKDEP의 ONSTACK 선언은 실행 중 초기화 경로를 사용합니다.
 * 새 대기열은 등록이나 깨움 전에 초기화하세요. 사용 중인 대기열을 재초기화하여 연결을 잃지 않게 합니다. 스택에 만든 대기열은 기다리는 task와 관련 콜백이 더 이상 접근하지 않을 때까지 살아 있어야 합니다.
 */
void __init_waitqueue_head(struct wait_queue_head *wq_head, const char *name, struct lock_class_key *key)
{
	spin_lock_init(&wq_head->lock);
	lockdep_set_class_and_name(&wq_head->lock, key, name);
	INIT_LIST_HEAD(&wq_head->head);
}

EXPORT_SYMBOL(__init_waitqueue_head);

void add_wait_queue(struct wait_queue_head *wq_head, struct wait_queue_entry *wq_entry)
{
	unsigned long flags;

	wq_entry->flags &= ~WQ_FLAG_EXCLUSIVE;
	spin_lock_irqsave(&wq_head->lock, flags);
	__add_wait_queue(wq_head, wq_entry);
	spin_unlock_irqrestore(&wq_head->lock, flags);
}
EXPORT_SYMBOL(add_wait_queue);

void add_wait_queue_exclusive(struct wait_queue_head *wq_head, struct wait_queue_entry *wq_entry)
{
	unsigned long flags;

	wq_entry->flags |= WQ_FLAG_EXCLUSIVE;
	spin_lock_irqsave(&wq_head->lock, flags);

/* 학습 해설
 * Waitqueue active·잠금 없는 관측과 놓친 깨움
 * 실제 Linux 대기열의 구조와 등록·조건 검사·깨움·정리 순서를 읽어 잠드는 기술의 사용 조건을 배웁니다.
 * waitqueue_active는 리스트가 비었는지 조회할 뿐 잠금을 잡지 않습니다. waker가 조건을 true로 바꾼 뒤 이 조회로 wake 호출을 생략하려면 원문이 요구하는 메모리 배리어 또는 대기열 잠금 규약을 지켜야 합니다. 그렇지 않으면 waker는 빈 리스트를 보고 waiter는 이전 조건을 보아 서로의 변경을 놓칠 수 있습니다. 관측 결과가 task 소유권이나 객체 수명까지 보장하지는 않습니다.
 * 헤더의 CPU0·CPU1 순서도를 따라 조건 변경, smp_mb, 리스트 관측, prepare와 조건 재검사의 순서를 적어 보세요. 단순 최적화라고 배리어를 제거하지 마세요. 반환값은 그 순간의 리스트 관측으로 해석합니다.
 */
static inline int waitqueue_active(struct wait_queue_head *wq_head)
{
	return !list_empty(&wq_head->head);
}

/**
 * wq_has_single_sleeper - check if there is only one sleeper
 * @wq_head: wait queue head
 *
 * Returns true of wq_head has only one sleeper on the list.
 *
 * Please refer to the comment for waitqueue_active.
 */
static inline bool wq_has_single_sleeper(struct wait_queue_head *wq_head)
{
	return list_is_singular(&wq_head->head);
}

/**
 * wq_has_sleeper - check if there are any waiting processes
 * @wq_head: wait queue head
 *
 * Returns true if wq_head has waiting processes
 *
 * Please refer to the comment for waitqueue_active.
 */

/* 학습 해설
 * Waitqueue sleeper 조회·단일 항목과 배리어 포함 검사
 * 실제 Linux 대기열의 구조와 등록·조건 검사·깨움·정리 순서를 읽어 잠드는 기술의 사용 조건을 배웁니다.
 * wq_has_single_sleeper는 list_is_singular로 리스트에 항목이 하나인지 검사합니다. 이 이름만으로 그 task가 현재 잠들어 있다고 증명할 수는 없습니다. wq_has_sleeper는 smp_mb를 실행한 뒤 waitqueue_active를 호출합니다. 이 배리어는 기다리는 쪽의 배리어와 짝을 이루며, 단순 리스트 수 조회와 메모리 순서 보조를 구별해야 합니다.
 * 단일 항목 검사는 active 주석의 사용 조건을 함께 따르세요. wq_has_sleeper를 사용하더라도 객체 수명, 리스트 변경 직렬화, 조건 변경과의 전체 프로토콜을 지켜야 합니다. 항목 수를 실제 sleeping task 수로 단정하지 마세요.
 */
static inline bool wq_has_sleeper(struct wait_queue_head *wq_head)
{
	/*
	 * We need to be sure we are in sync with the
	 * add_wait_queue modifications to the wait queue.
	 *
	 * This memory barrier should be paired with one on the
	 * waiting side.
	 */
	smp_mb();
	return waitqueue_active(wq_head);
}

extern void add_wait_queue(struct wait_queue_head *wq_head, struct wait_queue_entry *wq_entry);
extern void add_wait_queue_exclusive(struct wait_queue_head *wq_head, struct wait_queue_entry *wq_entry);
extern void add_wait_queue_priority(struct wait_queue_head *wq_head, struct wait_queue_entry *wq_entry);
extern void remove_wait_queue(struct wait_queue_head *wq_head, struct wait_queue_entry *wq_entry);

static inline void __add_wait_queue(struct wait_queue_head *wq_head, struct wait_queue_entry *wq_entry)
{
	struct list_head *head = &wq_head->head;
	struct wait_queue_entry *wq;

	list_for_each_entry(wq, &wq_head->head, entry) {
		if (!(wq->flags & WQ_FLAG_PRIORITY))
			break;

/* 학습 해설
 * Waitqueue 등록 순서·priority 앞부분과 일반 항목
 * 실제 Linux 대기열의 구조와 등록·조건 검사·깨움·정리 순서를 읽어 잠드는 기술의 사용 조건을 배웁니다.
 * __add_wait_queue는 리스트 처음부터 WQ_FLAG_PRIORITY 항목이 연속하는 구간을 지나갑니다. 이후 그 위치에 새 항목을 삽입하여 기존 priority 앞부분을 유지합니다. priority가 없는 일반 항목은 그 뒤의 앞쪽에 들어가므로 일반 항목 전체가 FIFO가 되는 것은 아닙니다. 이 내부 helper는 대기열 잠금을 스스로 잡지 않습니다.
 * 일반 등록은 add_wait_queue 같은 잠금 포함 API로 수행하세요. 내부 helper를 직접 사용할 때는 head 잠금이 이미 보호하는 문맥이어야 합니다. priority 순서와 일반 항목 순서, exclusive 예산을 각각 구분합니다.
 */
static inline void __add_wait_queue(struct wait_queue_head *wq_head, struct wait_queue_entry *wq_entry)
{
	struct list_head *head = &wq_head->head;
	struct wait_queue_entry *wq;

	list_for_each_entry(wq, &wq_head->head, entry) {
		if (!(wq->flags & WQ_FLAG_PRIORITY))
			break;
		head = &wq->entry;
	}
	list_add(&wq_entry->entry, head);
}

/*
 * Used for wake-one threads:
 */
static inline void
__add_wait_queue_exclusive(struct wait_queue_head *wq_head, struct wait_queue_entry *wq_entry)
{
	wq_entry->flags |= WQ_FLAG_EXCLUSIVE;
	__add_wait_queue(wq_head, wq_entry);
}

static inline void __add_wait_queue_entry_tail(struct wait_queue_head *wq_head, struct wait_queue_entry *wq_entry)
{
	list_add_tail(&wq_entry->entry, &wq_head->head);

/* 학습 해설
 * Waitqueue exclusive·플래그와 tail 등록
 * 실제 Linux 대기열의 구조와 등록·조건 검사·깨움·정리 순서를 읽어 잠드는 기술의 사용 조건을 배웁니다.
 * add_wait_queue_exclusive는 EXCLUSIVE 플래그를 설정하고 IRQ 상태를 저장하며 head 잠금을 잡은 뒤 tail에 삽입합니다. 일반 add_wait_queue는 EXCLUSIVE를 지우고 priority 뒤의 앞쪽에 삽입합니다. add_wait_queue_priority는 EXCLUSIVE와 PRIORITY를 함께 설정하고 앞쪽 priority 구간에 넣습니다. exclusive는 깨움 예산의 소비 규칙이며, 조건 데이터의 상호 배제 잠금은 아닙니다.
 * 한 번의 사건으로 일부 대기자만 처리하게 하려면 exclusive 규칙과 실제 조건 소비를 함께 설계합니다. flag 이름만으로 공유 데이터가 보호된다고 가정하지 마세요. 이미 등록된 같은 항목을 중복으로 삽입하지 않습니다.
 */
void add_wait_queue_exclusive(struct wait_queue_head *wq_head, struct wait_queue_entry *wq_entry)
{
	unsigned long flags;

	wq_entry->flags |= WQ_FLAG_EXCLUSIVE;
	spin_lock_irqsave(&wq_head->lock, flags);
	__add_wait_queue_entry_tail(wq_head, wq_entry);
	spin_unlock_irqrestore(&wq_head->lock, flags);
}
EXPORT_SYMBOL(add_wait_queue_exclusive);

void add_wait_queue_priority(struct wait_queue_head *wq_head, struct wait_queue_entry *wq_entry)
{
	unsigned long flags;

	wq_entry->flags |= WQ_FLAG_EXCLUSIVE | WQ_FLAG_PRIORITY;
